window.__votdWeek && window.__votdWeek({"week":"2028-01-24","reading":"1 Nephi 16–22","days":[{"d":"2028-01-24","ref":"1 Nephi 17:28","b":"1 Nephi","c":17,"v":28,"he":"וְגַם־יְדַעְתֶּם כִּי כֻלְכְּלוּ בַּמָּן בַּמִּדְבָּר׃","en":"And ye also know that they were fed with manna in the wilderness."},{"d":"2028-01-25","ref":"1 Nephi 17:29","b":"1 Nephi","c":17,"v":29,"he":"וְאַף גַּם־יְדַעְתֶּם כִּי מֹשֶׁה לְפִי כֹּחַ הָאֱלֹהִים אֲשֶׁר־בּוֹ הִכָּה בִּדְבָרוֹ אֶת־הַסֶּלַע וַיֵּצְאוּ מַיִם לְמַעַן יִרְווּ בְּנֵי יִשְׂרָאֵל צְמָאָם׃","en":"Yea, and ye also know that Moses, by his word according to the power of God which was in him, smote the rock, and there came forth water, that the children of Israel might quench their thirst."},{"d":"2028-01-26","ref":"1 Nephi 18:16","b":"1 Nephi","c":18,"v":16,"he":"אַךְ נָשָׂאתִי עֵינַי אֶל־אֱלֹהַי וַאֲהַלְלֶנּוּ כׇּל־הַיּוֹם וְלֹא הֲלִינוֹתִי עַל־יְהוָה בַּעֲבוּר צָרוֹתָי׃","en":"Nevertheless, I did look unto my God, and I did praise him all the day long; and I did not murmur against the Lord because of mine afflictions."},{"d":"2028-01-27","ref":"1 Nephi 19:14","b":"1 Nephi","c":19,"v":14,"he":"וּבַעֲבוּר אֲשֶׁר הִטּוּ לְבָבָם אָמַר הַנָּבִיא וּבָזוּ אֶת־קְדוֹשׁ יִשְׂרָאֵל יָנוּדוּ בַּבָּשָׂר וְיֹאבֵדוּ וְהָיוּ לִשְׁרֵקָה וּלְמָשָׁל וּשְׂנוּאִים בְּכׇל־הַגּוֹיִם׃","en":"And because they turn their hearts aside, saith the prophet, and have despised the Holy One of Israel, they shall wander in the flesh, and perish, and become a hiss and a byword, and be hated among all nations."},{"d":"2028-01-28","ref":"1 Nephi 19:16","b":"1 Nephi","c":19,"v":16,"he":"וְאַף אָז יִזְכֹּר אֶת־אִיֵּי הַיָּם וְאַף אֶת־כׇּל־הָעָם אֲשֶׁר מִבֵּית יִשְׂרָאֵל אֲקַבְּצֵם נְאֻם־יְהוָה כְּדִבְרֵי הַנָּבִיא זֶנוֹס מֵאַרְבַּע כַּנְפוֹת הָאָרֶץ׃","en":"Yea, then will he remember the isles of the sea; yea, and all the people who are of the house of Israel, will I gather in, saith the Lord, according to the words of the prophet Zenos, from the four quarters of the earth."},{"d":"2028-01-29","ref":"1 Nephi 22:3","b":"1 Nephi","c":22,"v":3,"he":"לָכֵן הַדְּבָרִים אֲשֶׁר קָרָאתִי דִּבְרֵי הַבָּשָׂר וְהָרוּחַ הֵם גַּם־יָחַד כִּי נִרְאֶה כִּי יִתְפַּזֵּר בֵּית־יִשְׂרָאֵל אִם מְהֵרָה וְאִם אַחֲרֵי־כֵן עַל־כׇּל־פְּנֵי הָאָרֶץ וְגַם בְּתוֹךְ כׇּל־הַגּוֹיִם׃","en":"Wherefore, the things of which I have read are things pertaining to things both temporal and spiritual; for it appears that the house of Israel, sooner or later, will be scattered upon all the face of the earth, and also among all nations."},{"d":"2028-01-30","ref":"1 Nephi 22:16","b":"1 Nephi","c":22,"v":16,"he":"כִּי קְרוֹבָה הָעֵת אֲשֶׁר תִּשָּׁפֵךְ חֲמַת אֱלֹהִים בִּמְלוֹאָהּ עַל־כׇּל־בְּנֵי הָאָדָם כִּי־לֹא יִתֵּן לָרְשָׁעִים לְהַשְׁחִית אֶת־הַצַּדִּיקִים׃","en":"For the time soon cometh that the fulness of the wrath of God shall be poured out upon all the children of men; for he will not suffer that the wicked shall destroy the righteous."}]});
